<?phpApp::uses('AppController', 'Controller');class TermsController extends AppController {        public function beforeFilter() {        parent::beforeFilter();        $this->layout = '';    }        public function privacy_policy(){}        public function refund_policy(){}        public function termandcondition(){}        public function showCaptcha(){    	session_start();    	    	$random = rand(1, 9).rand(1, 9).rand(1, 9);    	    	$_SESSION['captcha'] = $random;    	    	$captcha = imagecreatefromjpeg(WWW_ROOT.'img'.DS."captcha.jpg");    	$color = imagecolorallocate($captcha, 0, 0, 0);    	$font = WWW_ROOT.'img'.DS.'code.otf';     	imagettftext($captcha, 20, 0, rand(30, 200), rand(20, 70), $color, $font, $random );    	imagepng($captcha);    	imagedestroy($captcha);    	exit;    }        public function about(){            }}